-- SEO meta refresh for every live SG category page with courses: 252 categories.
--
-- Audit (2026-10-24, prod SG): category metas had drifted from the courses actually listed (e.g. cat 5
-- "WSQ Finance Courses" titled "Urban Farming & Landscaping Courses"), 174 descriptions ran past 160
-- chars, 17 titles / 19 descriptions were empty, 114 titles baked the brand, and 11 categories with no
-- funded course still claimed WSQ/SkillsFuture funding.
--
-- New values, written from each category's name + parents + listed courses:
--   meta_title       BARE (MMD_Seotitle appends "| Tertiary Courses Singapore"), <= 50 chars, unique.
--   meta_description 130-160 chars (TEXT attribute). Funding wording only where funded courses are listed;
--                    never UTAP.
--   meta_keywords    5-8 phrases (TEXT).
-- Store-view overrides of the three attributes are removed so the store-0 value renders; the category flat
-- table is mirrored when present. Name / url_key / is_active untouched. Empty categories (38) are skipped.
-- Rows are keyed by entity_id AND current name, so a category renamed since the audit is left alone.
--
-- SG-only (store guard) -> no-op on MY/GH (category ids differ per partner). Idempotent.
-- Post-deploy: catalog_category_flat reindex + cache flush.

SET @sg := (SELECT COUNT(*) FROM core_store WHERE store_id = 1 AND code = 'singapore');
SET @c_name   := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 3 AND attribute_code = 'name');
SET @c_mtitle := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 3 AND attribute_code = 'meta_title' AND backend_type = 'varchar');
SET @c_mdesc  := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 3 AND attribute_code = 'meta_description' AND backend_type = 'text');
SET @c_mkey   := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 3 AND attribute_code = 'meta_keywords' AND backend_type = 'text');
SET @ok := (@sg = 1 AND @c_mtitle IS NOT NULL AND @c_mdesc IS NOT NULL AND @c_mkey IS NOT NULL);

DROP TABLE IF EXISTS mms_seo_cat_meta_stage;

CREATE TABLE mms_seo_cat_meta_stage (
  id   INT UNSIGNED NOT NULL PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  mt   VARCHAR(255) NOT NULL,
  md   TEXT NOT NULL,
  mk   TEXT NOT NULL
) DEFAULT CHARSET = utf8;


-- keep only categories whose current (store-1 else store-0) name still matches the audit
DELETE s FROM mms_seo_cat_meta_stage s
  LEFT JOIN catalog_category_entity_varchar n0 ON n0.entity_id = s.id AND n0.attribute_id = @c_name AND n0.store_id = 0
  LEFT JOIN catalog_category_entity_varchar n1 ON n1.entity_id = s.id AND n1.attribute_id = @c_name AND n1.store_id = 1
 WHERE TRIM(COALESCE(n1.value, n0.value, '')) <> s.name;

SELECT 3, @c_mtitle, 0, s.id, s.mt FROM mms_seo_cat_meta_stage s WHERE @ok
ON DUPLICATE KEY UPDATE value = VALUES(value);

SELECT 3, @c_mdesc, 0, s.id, s.md FROM mms_seo_cat_meta_stage s WHERE @ok
ON DUPLICATE KEY UPDATE value = VALUES(value);

SELECT 3, @c_mkey, 0, s.id, s.mk FROM mms_seo_cat_meta_stage s WHERE @ok
ON DUPLICATE KEY UPDATE value = VALUES(value);

DELETE v FROM catalog_category_entity_varchar v JOIN mms_seo_cat_meta_stage s ON s.id = v.entity_id
 WHERE @ok AND v.attribute_id = @c_mtitle AND v.store_id <> 0;

DELETE t FROM catalog_category_entity_text t JOIN mms_seo_cat_meta_stage s ON s.id = t.entity_id
 WHERE @ok AND t.attribute_id IN (@c_mdesc, @c_mkey) AND t.store_id <> 0;

-- mirror into the store-1 category flat table when it exists (reindex would do the same)
SET @has_flat := (SELECT COUNT(*) FROM information_schema.COLUMNS
                   WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'catalog_category_flat_store_1'
                     AND COLUMN_NAME IN ('meta_title', 'meta_description', 'meta_keywords'));
SET @q := IF(@ok AND @has_flat = 3,
  'UPDATE catalog_category_flat_store_1 f JOIN mms_seo_cat_meta_stage s ON s.id = f.entity_id SET f.meta_title = s.mt, f.meta_description = s.md, f.meta_keywords = s.mk',
  'DO 0');
PREPARE st FROM @q;
EXECUTE st;
DEALLOCATE PREPARE st;

DROP TABLE IF EXISTS mms_seo_cat_meta_stage;
